sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float spacing;
uniform float darkness;
uniform float roll_speed;
half4 main(float2 coord) {
    float y = coord.y + time * roll_speed * 60.0;
    float line = fract(y / spacing);
    float scan = 1.0 - darkness * (line < 0.5 ? 1.0 : 0.0);
    half4 c = image.eval(coord);
    if (c.a <= 0.0) return c;
    half3 rgb = c.rgb / c.a;
    rgb *= scan;
    c.rgb = rgb * c.a;
    return c;
}
